<body>
  <canvas id="c"></canvas>
  <div id="hud">Black Hole<small>Gravitational Lensing &middot; Accretion Disk</small></div>
  <div id="info"><b>DRAG</b> orbit &nbsp;&middot;&nbsp; <b>SCROLL</b> zoom</div>
  <div id="loading">DIGGING THE EVENT HORIZON&hellip;</div>

  <script type="importmap">
  {
    "imports": {
      "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
      "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
    }
  }
  </script>

  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
    import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
    import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
    import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

    const canvas = document.getElementById('c');
    const loading = document.getElementById('loading');

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      powerPreference: 'high-performance',
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.15;
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x010102);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 2000);
    camera.position.set(4, 14, 46);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.55;
    controls.minDistance = 10;
    controls.maxDistance = 380;
    controls.target.set(0, 0, 0);

    /* ---------------- Constants (world units) ---------------- */
    const BH_RADIUS  = 8.0;      // rendered event-horizon sphere radius
    const GRAV_ACC   = 200.0;    // shader gravity "strength"
    const DISK_DIST  = 42.0;     // accretion disk centre offset along +z
    const DISK_RAD   = 88.0;     // accretion disk radius
    const DISK_RING  = 62.0;     // soft outer falloff start

    /* ---------------- Lensing back-drop (skydome shader) -------- */
    const domeVertex = `
      varying vec3 vWorldPos;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorldPos = wp.xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `;

    const domeFragment = `
      precision highp float;
      uniform float uTime;
      varying vec3 vWorldPos;

      const float BH_RADIUS  = ${BH_RADIUS.toFixed(1)};
      const float DISK_DIST  = ${DISK_DIST.toFixed(1)};
      const float DISK_RAD   = ${DISK_RAD.toFixed(1)};
      const float DISK_RING  = ${DISK_RING.toFixed(1)};

      float hash21(vec2 p) {
        vec3 p3 = fract(vec3(p.xyx) * 0.1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
      }

      /* Procedural starfield sampled along a direction. */
      vec3 sampleStars(vec3 dir) {
        vec2 uv = vec2(atan(dir.z, dir.x), asin(clamp(dir.y, -1.0, 1.0)));
        float grid = 340.0 / 6.2831853;
        vec3 col = vec3(0.0);
        for (int layer = 0; layer < 2; layer++) {
          float scale = (layer == 0) ? 1.0 : 5.0;
          vec2 c = floor(uv * grid * scale);
          float h  = hash21(c);
          float h2 = hash21(c + 61.7);
          float star = smoothstep(0.9950, 1.0, h);
          vec3 tint = mix(vec3(0.72, 0.82, 1.0), vec3(1.0, 0.72, 0.45), step(0.5, h2));
          col += star * tint * (0.35 + 5.5 * (h - 0.9950)) / scale;
        }
        return col;
      }

      /* Accretion disk: infinite plane at y=0, truncated to a disc. */
      vec4 intersectDisk(vec3 rayPos, vec3 rayDir) {
        float fDist = -rayPos.y / max(rayDir.y, 0.0001);
        if (rayDir.y > -0.0001 || fDist <= 0.0) return vec4(0.0);
        vec3 p = rayPos + rayDir * fDist;
        float r = length(vec2(p.x, p.z - DISK_DIST));
        if (r > DISK_RAD) return vec4(0.0);

        float t = smoothstep(DISK_RING, DISK_RAD, r);          // outer fade
        float fInterp = clamp(r / (BH_RADIUS * 12.0), 0.0, 1.0);

        vec3 col = vec3(1.0, 1.0, 1.0);
        col *= 1.0 - 0.62 * fInterp;                            // dim slightly with radius
        col *= vec3(1.0, 0.62, 0.26) * 2.1;                     // warm amber

        float grad = clamp(p.y * 0.02 / pow(max(r / BH_RADIUS, 1e-4), 4.0), 0.12, 1.0);
        col *= grad;

        float hot = 1.0 - smoothstep(BH_RADIUS * 0.9, BH_RADIUS * 2.2, r); // white-hot inner rim
        col += vec3(1.0, 0.96, 0.85) * hot * 1.6;

        float sheen = smoothstep(0.45, 0.0, abs(p.y)) * 0.6;    // thin extremely bright plane
        col += vec3(1.0, 0.9, 0.7) * sheen * 2.2;

        return vec4(col, 1.0) * (1.0 - t);
      }

      void ApplyGravity(inout vec3 pPos, inout vec3 pDir, float stepLen) {
        vec3 toTarget = vec3(0.0) - pPos;
        float distSqr = dot(toTarget, toTarget);
        float acc = ${GRAV_ACC.toFixed(1)} / distSqr;
        pDir -= normalize(toTarget) * acc;
        pDir = normalize(pDir);
        pPos += pDir * stepLen;
      }

      void main() {
        vec3 rayDir = normalize(vWorldPos - cameraPosition);
        vec3 p = cameraPosition;
        vec3 d = rayDir;

        for (int i = 0; i < 4; i++) {
          ApplyGravity(p, d, 9.0);
        }

        vec3 col = sampleStars(d);
        vec4 disk = intersectDisk(p, d);
        if (disk.a > 0.003) {
          col = mix(col, disk.rgb, min(1.0, disk.a));
        }
        gl_FragColor = vec4(col, 1.0);
      }
    `;

    const dome = new THREE.Mesh(
      new THREE.SphereGeometry(600, 96, 96),
      new THREE.ShaderMaterial({
        uniforms: { uTime: { value: 0 } },
        vertexShader: domeVertex,
        fragmentShader: domeFragment,
        side: THREE.BackSide,
        depthWrite: false,
      })
    );
    dome.renderOrder = -1;
    scene.add(dome);

    /* ---------------- Event horizon sphere ---------------------- */
    const horizon = new THREE.Mesh(
      new THREE.SphereGeometry(BH_RADIUS, 96, 96),
      new THREE.ShaderMaterial({
        vertexShader: `
          varying vec3 vNormal;
          varying vec3 vView;
          void main() {
            vNormal = normalize(normalMatrix * normal);
            vec4 mv = modelViewMatrix * vec4(position, 1.0);
            vView = -mv.xyz;
            gl_Position = projectionMatrix * mv;
          }`,
        fragmentShader: `
          varying vec3 vNormal;
          varying vec3 vView;
          void main() {
            vec3 n = normalize(vNormal);
            vec3 v = normalize(vView);
            float rim = pow(1.0 - abs(dot(n, v)), 5.0);
            vec3 col = vec3(0.004, 0.001, 0.001) + vec3(1.0, 0.35, 0.10) * rim * 0.42;
            gl_FragColor = vec4(col, 1.0);
          }`,
      })
    );
    scene.add(horizon);

    /* ---------------- Photon ring (bright arc for bloom) -------- */
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xffa64d,
      transparent: true,
      opacity: 0.5,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(15.6, 0.32, 24, 160), ringMat);
    ring.rotation.x = Math.PI / 2 * 0.985;
    ring.renderOrder = 2;
    scene.add(ring);

    const haloMat = ringMat.clone();
    haloMat.color.set(0xff5a16);
    haloMat.opacity = 0.16;
    const halo = new THREE.Mesh(new THREE.TorusGeometry(15.6, 2.8, 40, 160), haloMat);
    halo.rotation.x = ring.rotation.x;
    halo.renderOrder = 1;
    scene.add(halo);

    /* ---------------- Accretion disk particles ------------------- */
    const PARTICLE_COUNT = 9000;
    const pos = new Float32Array(PARTICLE_COUNT * 3);
    const colArr = new Float32Array(PARTICLE_COUNT * 3);
    const meta = new Float32Array(PARTICLE_COUNT * 3); // radius, theta0, speed

    const innerR = 11.0, outerR = 52.0;
    const cInner = new THREE.Color(1.0, 0.97, 0.92);
    const cMid   = new THREE.Color(1.0, 0.55, 0.16);
    const cOuter = new THREE.Color(0.55, 0.14, 0.05);

    for (let i = 0; i < PARTICLE_COUNT; i++) {
      const u = Math.random();
      const r = innerR + (outerR - innerR) * Math.pow(u, 0.62);
      const theta = Math.random() * Math.PI * 2;
      const y = (Math.random() - 0.5) * 1.1 * (1.0 - (r - innerR) / (outerR - innerR) + 0.15);
      meta[i * 3 + 0] = r;
      meta[i * 3 + 1] = theta;
      const kepler = Math.sqrt(3.4 / Math.pow(r, 3.0));
      meta[i * 3 + 2] = kepler * (0.85 + Math.random() * 0.35);
      pos[i * 3 + 0] = Math.cos(theta) * r;
      pos[i * 3 + 1] = y;
      pos[i * 3 + 2] = -Math.sin(theta) * r;

      const tint = (r - innerR) / (outerR - innerR);
      const c = cInner.clone().lerp(cMid, Math.min(1, tint * 1.4));
      if (tint > 0.72) c.lerp(cOuter, (tint - 0.72) / 0.28);
      const twinkle = 0.55 + 0.45 * Math.random();
      colArr[i * 3 + 0] = c.r * twinkle;
      colArr[i * 3 + 1] = c.g * twinkle;
      colArr[i * 3 + 2] = c.b * twinkle;
    }

    const pGeo = new THREE.BufferGeometry();
    pGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    pGeo.setAttribute('color', new THREE.BufferAttribute(colArr, 3));

    const pMat = new THREE.PointsMaterial({
      size: 0.42,
      vertexColors: true,
      transparent: true,
      opacity: 0.95,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true,
    });
    const particles = new THREE.Points(pGeo, pMat);
    particles.renderOrder = 3;
    scene.add(particles);

    /* ---------------- Background glow fog ----------------------- */
    scene.fog = new THREE.FogExp2(0x000000, 0.0009);

    /* ---------------- Post processing (bloom) -------------------- */
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));
    const bloom = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      1.25,   // strength
      0.75,   // radius
      0.30    // threshold
    );
    composer.addPass(bloom);

    /* ---------------- Resize ------------------------------------ */
    window.addEventListener('resize', () => {
      const w = window.innerWidth, h = window.innerHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
      composer.setSize(w, h);
    });

    /* ---------------- Animate ----------------------------------- */
    const clock = new THREE.Clock();
    const posAttr = pGeo.attributes.position;
    const tmpPos = new Float32Array(PARTICLE_COUNT * 3);

    function animate() {
      requestAnimationFrame(animate);
      const dt = Math.min(clock.getDelta(), 0.1);
      const t = clock.elapsedTime;

      dome.material.uniforms.uTime.value = t;
      ring.rotation.z += dt * 0.12;
      halo.rotation.z -= dt * 0.06;

      const arr = posAttr.array;
      for (let i = 0; i < PARTICLE_COUNT; i++) {
        const r = meta[i * 3];
        const th = meta[i * 3 + 1] + t * meta[i * 3 + 2];
        const band = 1.0 - Math.min(1.0, (r - innerR) / (outerR - innerR));
        const y = Math.sin(t * (0.7 + r * 0.05) + r) * 0.45 * band;
        const j = i * 3;
        tmpPos[j + 0] = Math.cos(th) * r;
        tmpPos[j + 1] = y;
        tmpPos[j + 2] = -Math.sin(th) * r;
      }
      posAttr.array.set(tmpPos);
      posAttr.needsUpdate = true;

      controls.update();
      composer.render();
    }

    function boot() {
      animate();
      requestAnimationFrame(() => requestAnimationFrame(() => loading.classList.add('hidden')));
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', boot);
    } else {
      boot();
    }
  </script>
