  gl.readPixels(0,0,w,h,gl.RGBA,gl.UNSIGNED_BYTE,buf);
  let sum=0, total=0, brightPx=0, yellowPx=0, bluePx=0;
  // count pixels per band of radius from center
  const cx=w/2, cy=h/2;
  const ringCounts=new Array(40).fill(0);
  const ch=" .:-=+*#%@";
